begin;\n\n-- Runtime state-machine integration for draw and payout RPCs.\n\ncreate or replace function public.prepare_draw_for_admin(target_cycle_id uuid)\nreturns uuid language plpgsql security definer set search_path=public as $$ declare session_id uuid; cycle_kuri_id uuid; cycle_status_value public.cycle_status; begin if auth.uid() is null then raise exception 'You must be signed in.'; end if; select c.kuri_id,c.status into cycle_kuri_id,cycle_status_value from public.cycles c join public.kuris k on k.id=c.kuri_id where c.id=target_cycle_id and exists(select 1 from public.organization_users ou where ou.organization_id=k.organization_id and ou.user_id=auth.uid() and ou.role=any(array['MAIN_ADMIN','ADMIN']::public.app_role[])); if cycle_kuri_id is null then raise exception 'You do not have permission to manage this draw.'; end if; if cycle_status_value not in ('PAYMENT_CLOSED','DRAW_PENDING') then raise exception 'Cycle must be PAYMENT_CLOSED or DRAW_PENDING before preparing a draw.'; end if; select d.id into session_id from public.draw_sessions d where d.cycle_id=target_cycle_id; if session_id is null then insert into public.draw_sessions(kuri_id,cycle_id,conducted_by,status,started_at) values(cycle_kuri_id,target_cycle_id,(select id from public.users where id=auth.uid()),'DRAFT',now()) returning id into session_id; end if; insert into public.draw_pool_entries(draw_session_id,membership_id,system_eligible,admin_included,override,modified_by,modified_at) select session_id,m.id,(i.status in ('PAID','PAID_LATE')),(i.status in ('PAID','PAID_LATE')),false,(select id from public.users where id=auth.uid()),now() from public.memberships m join public.installments i on i.membership_id=m.id where i.cycle_id=target_cycle_id on conflict(draw_session_id,membership_id) do nothing; delete from public.draw_selections where draw_session_id=session_id; if (select status from public.draw_sessions where id=session_id)='DRAFT' then perform public.transition_draw_status_for_admin(session_id,'POOL_READY'); elsif (select status from public.draw_sessions where id=session_id)<>'POOL_READY' then raise exception 'Draw session is already finalized or otherwise unavailable for preparation.'; end if; return session_id; end $$;\n\ncreate or replace function public.set_draw_pool_entry_for_admin(target_entry_id uuid,include_in_draw boolean,reason_text text default null) returns void language plpgsql security definer set search_path=public as $$ declare org_id uuid; session_status public.draw_status; begin select k.organization_id,d.status into org_id,session_status from public.draw_pool_entries e join public.draw_sessions d on d.id=e.draw_session_id join public.cycles c on c.id=d.cycle_id join public.kuris k on k.id=c.kuri_id where e.id=target_entry_id; if org_id is null then raise exception 'Draw pool entry not found.'; end if; if not exists(select 1 from public.organization_users ou where ou.organization_id=org_id and ou.user_id=auth.uid() and ou.role=any(array['MAIN_ADMIN','ADMIN']::public.app_role[])) then raise exception 'You do not have permission to modify this draw pool.'; end if; if session_status<>'POOL_READY' then raise exception 'Draw pool can only be modified while the draw is POOL_READY.'; end if; update public.draw_pool_entries set admin_included=include_in_draw,override=(include_in_draw<>system_eligible),override_reason=nullif(btrim(reason_text),''),modified_by=(select id from public.users where id=auth.uid()),modified_at=now() where id=target_entry_id; if not found then raise exception 'Draw pool entry not found.'; end if; end $$;\n\ncreate or replace function public.run_random_draw_for_admin(target_cycle_id uuid,selection_count integer default 1) returns table(selection_order integer,membership_id uuid,membership_number text,registered_name text,display_name text,randomization_id text) language plpgsql security definer set search_path=public as $$ declare session_id uuid; candidate_count integer; draw_status_value public.draw_status; begin if selection_count is null or selection_count<1 then raise exception 'Selection count must be at least 1.'; end if; select d.id,d.status into session_id,draw_status_value from public.draw_sessions d join public.cycles c on c.id=d.cycle_id join public.kuris k on k.id=c.kuri_id where d.cycle_id=target_cycle_id and exists(select 1 from public.organization_users ou where ou.organization_id=k.organization_id and ou.user_id=auth.uid() and ou.role=any(array['MAIN_ADMIN','ADMIN']::public.app_role[])); if session_id is null then raise exception 'Prepare the draw first.'; end if; if draw_status_value<>'POOL_READY' then raise exception 'Draw must be POOL_READY before running the random draw.'; end if; select count(*) into candidate_count from public.draw_pool_entries e where e.draw_session_id=session_id and e.admin_included; if candidate_count=0 then raise exception 'No memberships are included in the draw pool.'; end if; if selection_count>candidate_count then raise exception 'Selection count exceeds the draw pool.'; end if; perform public.transition_draw_status_for_admin(session_id,'DRAWING'); delete from public.draw_selections where draw_session_id=session_id; insert into public.draw_selections(draw_session_id,membership_id,selection_order,randomization_id) select session_id,picked.membership_id,picked.rn,gen_random_uuid()::text from(select e.membership_id,row_number() over(order by random())::integer rn from public.draw_pool_entries e where e.draw_session_id=session_id and e.admin_included order by random() limit selection_count) picked; perform public.transition_draw_status_for_admin(session_id,'RESULTS_READY'); return query select s.selection_order,s.membership_id,m.membership_number,p.registered_name,p.display_name,s.randomization_id from public.draw_selections s join public.memberships m on m.id=s.membership_id join public.people p on p.id=m.person_id where s.draw_session_id=session_id order by s.selection_order; end $$;\n\ncreate or replace function public.finalize_draw_for_admin(target_cycle_id uuid,final_membership_ids uuid[]) returns integer language plpgsql security definer set search_path=public as $$ declare session_id uuid; target_kuri_id uuid; winner_count integer; selected_count integer; cycle_status_value public.cycle_status; draw_status_value public.draw_status; begin if auth.uid() is null then raise exception 'You must be signed in.'; end if; select d.id,c.kuri_id,c.status,d.status into session_id,target_kuri_id,cycle_status_value,draw_status_value from public.draw_sessions d join public.cycles c on c.id=d.cycle_id join public.kuris k on k.id=c.kuri_id where d.cycle_id=target_cycle_id and exists(select 1 from public.organization_users ou where ou.organization_id=k.organization_id and ou.user_id=auth.uid() and ou.role=any(array['MAIN_ADMIN','ADMIN']::public.app_role[])); if session_id is null then raise exception 'Prepare and run the draw before finalizing winners.'; end if; if cycle_status_value<>'DRAW_PENDING' then raise exception 'Cycle must be DRAW_PENDING before finalizing winners.'; end if; if draw_status_value<>'RESULTS_READY' then raise exception 'Draw must have RESULTS_READY status before finalizing winners.'; end if; if coalesce(array_length(final_membership_ids,1),0)<1 then raise exception 'Select at least one winner.'; end if; select count(*) into selected_count from public.draw_selections s where s.draw_session_id=session_id and s.membership_id=any(final_membership_ids); if selected_count<>array_length(final_membership_ids,1) then raise exception 'Final winners must come from the current draw selections.'; end if; if exists(select 1 from public.memberships m where m.id=any(final_membership_ids) and m.kuri_id<>target_kuri_id) then raise exception 'A selected membership does not belong to this Kuri.'; end if; if exists(select 1 from public.monthly_winners where cycle_id=target_cycle_id) then raise exception 'Winners are already finalized for this cycle.'; end if; insert into public.monthly_winners(cycle_id,person_id,selection_source,finalized_by,finalized_at) select target_cycle_id,m.person_id,'RANDOM_DRAW',(select id from public.users where id=auth.uid()),now() from public.memberships m where m.id=any(final_membership_ids); insert into public.monthly_winner_memberships(monthly_winner_id,membership_id) select mw.id,m.id from public.monthly_winners mw join public.memberships m on m.person_id=mw.person_id where mw.cycle_id=target_cycle_id and m.id=any(final_membership_ids); perform public.transition_draw_status_for_admin(session_id,'FINALIZED'); perform public.transition_cycle_status_for_admin(target_cycle_id,'COMPLETED'); select count(*) into winner_count from public.monthly_winners where cycle_id=target_cycle_id; return winner_count; end $$;\n\ncreate or replace function public.prepare_payout_for_admin(target_winner_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare payout_id uuid; winner_person_id uuid; winner_cycle_id uuid; gross_amount bigint; configured_muppu_amount bigint; deducted_muppu_amount bigint; payout_muppu_amount bigint; cycle_status_value public.cycle_status; begin select mw.person_id,mw.cycle_id,k.gross_prize_amount,k.muppu_amount,c.status into winner_person_id,winner_cycle_id,gross_amount,configured_muppu_amount,cycle_status_value from public.monthly_winners mw join public.cycles c on c.id=mw.cycle_id join public.kuris k on k.id=c.kuri_id where mw.id=target_winner_id and exists(select 1 from public.organization_users ou where ou.organization_id=k.organization_id and ou.user_id=auth.uid() and ou.role=any(array['MAIN_ADMIN','ADMIN']::public.app_role[])); if winner_person_id is null then raise exception 'Monthly winner not found.'; end if; if cycle_status_value<>'COMPLETED' then raise exception 'Cycle must be COMPLETED before preparing a payout.'; end if; if gross_amount<=0 then raise exception 'Gross prize amount must be greater than zero.'; end if; select coalesce(sum(mr.amount),0) into deducted_muppu_amount from public.muppu_records mr where mr.person_id=winner_person_id and mr.cycle_id=winner_cycle_id and mr.status='DEDUCTED'; payout_muppu_amount:=greatest(coalesce(configured_muppu_amount,0),deducted_muppu_amount); select po.id into payout_id from public.payouts po where po.monthly_winner_id=target_winner_id; if payout_id is null then insert into public.payouts(monthly_winner_id,gross_amount,muppu_amount,other_deductions,net_amount,status) values(target_winner_id,gross_amount,payout_muppu_amount,0,greatest(gross_amount-payout_muppu_amount,0),'PENDING') returning id into payout_id; else if (select status from public.payouts where id=payout_id)<>'PENDING' then return payout_id; end if; update public.payouts po set muppu_amount=payout_muppu_amount,net_amount=greatest(po.gross_amount-payout_muppu_amount-coalesce(po.other_deductions,0),0) where po.id=payout_id; end if; return payout_id; end $$;\n\ncreate or replace function public.mark_payout_paid_for_admin(target_winner_id uuid,payout_payment_date timestamptz,payout_method public.payment_method,payout_reference text default null,payout_notes text default null,payout_other_deductions bigint default 0) returns void language plpgsql security definer set search_path=public as $$ declare payout_row public.payouts%rowtype; target_org_id uuid; computed_net_amount bigint; begin if auth.uid() is null then raise exception 'You must be signed in.'; end if; if payout_other_deductions<0 then raise exception 'Other deductions cannot be negative.'; end if; select po.* into payout_row from public.payouts po where po.monthly_winner_id=target_winner_id; if not found then perform public.prepare_payout_for_admin(target_winner_id); select po.* into payout_row from public.payouts po where po.monthly_winner_id=target_winner_id; end if; select k.organization_id into target_org_id from public.monthly_winners mw join public.cycles c on c.id=mw.cycle_id join public.kuris k on k.id=c.kuri_id where mw.id=target_winner_id; if target_org_id is null then raise exception 'Monthly winner not found.'; end if; if not exists(select 1 from public.organization_users ou where ou.organization_id=target_org_id and ou.user_id=auth.uid() and ou.role=any(array['MAIN_ADMIN','ADMIN']::public.app_role[])) then raise exception 'You do not have permission to process this payout.'; end if; if payout_row.status<>'PENDING' then raise exception 'Only a PENDING payout can be marked PAID.'; end if; perform public.transition_payout_status_for_admin(payout_row.id,'PROCESSING'); computed_net_amount:=greatest(payout_row.gross_amount-payout_row.muppu_amount-payout_other_deductions,0); update public.payouts set other_deductions=payout_other_deductions,net_amount=computed_net_amount,payment_date=coalesce(payout_payment_date,now()),method=payout_method,reference_number=nullif(btrim(payout_reference),''),processed_by=(select id from public.users where id=auth.uid()),notes=nullif(btrim(payout_notes),'') where id=payout_row.id; perform public.transition_payout_status_for_admin(payout_row.id,'PAID'); end $$;\n\nrevoke all on function public.prepare_draw_for_admin(uuid) from public; revoke all on function public.set_draw_pool_entry_for_admin(uuid,boolean,text) from public; revoke all on function public.run_random_draw_for_admin(uuid,integer) from public; revoke all on function public.finalize_draw_for_admin(uuid,uuid[]) from public; revoke all on function public.prepare_payout_for_admin(uuid) from public; revoke all on function public.mark_payout_paid_for_admin(uuid,timestamptz,public.payment_method,text,text,bigint) from public; grant execute on function public.prepare_draw_for_admin(uuid) to authenticated; grant execute on function public.set_draw_pool_entry_for_admin(uuid,boolean,text) to authenticated; grant execute on function public.run_random_draw_for_admin(uuid,integer) to authenticated; grant execute on function public.finalize_draw_for_admin(uuid,uuid[]) to authenticated; grant execute on function public.prepare_payout_for_admin(uuid) to authenticated; grant execute on function public.mark_payout_paid_for_admin(uuid,timestamptz,public.payment_method,text,text,bigint) to authenticated;\n\ncommit;